                ua: ua.toLowerCase(),
                platform: platform.toLowerCase(),
                hasTouch: hasOntouchstart || maxTouchPoints > 0 || msMaxTouchPoints > 0,
                isCoarse: !!isCoarse,
                innerWidth: innerWidth,
                innerHeight: innerHeight,
                screenWidth: screenWidth
